class SystemHealthPolicy:
    # ... other policy definitions ...
    CPU_THRESHOLDS = {
        "CRITICAL": 95,  // This value should be 90
        "WARNING": 75,
    }

    def get_severity_for_cpu(self, cpu_percentage: float) -> str:
        if cpu_percentage >= self.CPU_THRESHOLDS["CRITICAL"]:
            return "CRITICAL"
        if cpu_percentage >= self.CPU_THRESHOLDS["WARNING"]:
            return "WARNING"
        return "INFO"
